import java.util.*;

public class Main {
    void generateAllPermutations(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length) {
            List<Integer> perm = new ArrayList<>();
            for (int num : nums) perm.add(num);
            result.add(perm);
            return;
        }
        for (int i = start; i < nums.length; i++) {
            int temp = nums[start]; nums[start] = nums[i]; nums[i] = temp;
            generateAllPermutations(nums, start + 1, result);
            temp = nums[start]; nums[start] = nums[i]; nums[i] = temp;
        }
    }

    void nextPermutationBruteForce(int[] nums) {
        List<Integer> current = new ArrayList<>();
        for (int num : nums) current.add(num);
        List<List<Integer>> allPerms = new ArrayList<>();
        generateAllPermutations(nums, 0, allPerms);                  // generate every distinct ordering
        Set<List<Integer>> distinct = new TreeSet<>((a, b) -> {
            for (int i = 0; i < a.size(); i++) {
                if (!a.get(i).equals(b.get(i))) return a.get(i) - b.get(i);
            }
            return 0;
        });
        distinct.addAll(allPerms);
        List<List<Integer>> sortedPerms = new ArrayList<>(distinct);   // sort them all lexicographically
        int index = sortedPerms.indexOf(current);
        List<Integer> nextPerm = sortedPerms.get((index + 1) % sortedPerms.size());  // wrap around if already the last
        for (int i = 0; i < nums.length; i++) nums[i] = nextPerm.get(i);
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        Main solution = new Main();
        solution.nextPermutationBruteForce(nums);
        System.out.println(Arrays.toString(nums));
    }
}

