public class Main {
    void nextPermutation(int[] nums) {
        int n = nums.length;
        int i = n - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) i--;               // find the end of the descending suffix
        if (i >= 0) {
            int j = n - 1;
            while (nums[j] <= nums[i]) j--;                            // find the smallest suffix value greater than pivot
            int temp = nums[i];
            nums[i] = nums[j];
            nums[j] = temp;                                             // swap the pivot with that value
        }
        int left = i + 1, right = n - 1;
        while (left < right) {
            int temp = nums[left];
            nums[left] = nums[right];
            nums[right] = temp;                                          // reverse the suffix into ascending order
            left++;
            right--;
        }
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        Main solution = new Main();
        solution.nextPermutation(nums);
        System.out.println(java.util.Arrays.toString(nums));
    }
}

