using namespace std;

void nextPermutation(vector<int>& nums) {
    int n = (int)nums.size();
    int i = n - 2;
    while (i >= 0 && nums[i] >= nums[i + 1]) i--;                 // find the end of the descending suffix
    if (i >= 0) {
        int j = n - 1;
        while (nums[j] <= nums[i]) j--;                              // find the smallest suffix value greater than pivot
        swap(nums[i], nums[j]);                                        // swap the pivot with that value
    }
    reverse(nums.begin() + i + 1, nums.end());                        // reverse the suffix into ascending order
}

